(()=>{const API='/api';const PREFIX='etd_';let ready=false,timer=null;const token=()=>parent.localStorage.getItem('et_access_token')||localStorage.getItem('et_access_token');const eligible=k=>k.startsWith(PREFIX)||k.startsWith('easyTagg');async function request(path,opt={}){const t=token();if(!t)return null;const r=await fetch(API+path,{...opt,headers:{'Content-Type':'application/json',Authorization:`Bearer ${t}`,...(opt.headers||{})},credentials:'include'});if(!r.ok)throw new Error('sync failed');return r.json()}
function snapshot(){const data={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&eligible(k))data[k]=localStorage.getItem(k)}return data}async function push(){if(!ready)return;try{await request('/sync/snapshot',{method:'PUT',body:JSON.stringify({data:snapshot()})})}catch(e){console.warn('Easy Tagg cloud sync:',e.message)}}function debounce(){clearTimeout(timer);timer=setTimeout(push,900)}
const original=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){original.call(this,k,v);if(this===localStorage&&eligible(String(k)))debounce()};const originalRemove=Storage.prototype.removeItem;Storage.prototype.removeItem=function(k){originalRemove.call(this,k);if(this===localStorage&&eligible(String(k)))debounce()};
(async()=>{try{const remote=await request('/sync/snapshot');if(remote?.data&&Object.keys(remote.data).length){Object.entries(remote.data).forEach(([k,v])=>{if(eligible(k)&&v!==null)original.call(localStorage,k,String(v))})}ready=true;window.dispatchEvent(new Event('easytagg-cloud-ready'));}catch(e){ready=true;console.warn('Easy Tagg cloud restore unavailable; local mode active.')}})();window.addEventListener('beforeunload',()=>{if(ready)push()});})();
